#include <queue>
#include <vector>
#include <functional>

// Default behavior: Max-Heap (uses std::less)
std::priority_queue<int> max_pq;
max_pq.push(5); max_pq.push(10);
// Output: 10 (max_pq.top())

// Customization: Min-Heap (uses std::greater)
// Note: The underlying container must also be specified
std::priority_queue<int, 
    std::vector<int>, 
    std::greater<int>> min_pq;

min_pq.push(5); min_pq.push(10);
// Output: 5 (min_pq.top())
